Ver el código en Python
versionC = {
  const t = tablaC, f0 = formatoNumero(0), f1 = formatoNumero(1);
  const p0 = (x) =&gt; formatoPorcentaje(x, 0), p1 = (x) =&gt; formatoPorcentaje(x, 1);
  const deficitTexto = (d) =&gt; (d &lt; 1e-6 ? "0" : d &lt;= 0.001 ? "&lt; 0,1 %" : p1(d));
  const nombres = {"mercado solo": "Dejar solo al mercado", "seguro CxC": "Cargo como el de 2019",
    "CxC por subasta": "Subasta de energía firme", "impulso FNCER": "Comprar 300 MW renovables al año",
    "paquete": "Subasta de firmeza y 150 MW renovables al año", "cargo 15 + FNCER 300": "Cargo bajo y 300 MW renovables al año"};
  const barras = (honesta) =&gt; t.estrategias.map((e, i) =&gt; ({nombre: nombres[e], min: Math.min(...t.extraRel[i]), max: Math.max(...t.extraRel[i]),
    raciona: t.deficitSequia[i] &gt; 0.001,
    etiqueta: honesta ? (t.deficitSequia[i] &gt; 0.001 ? `raciona ${p1(t.deficitSequia[i])}` : "no raciona (&lt; 0,1 %)") : ""}));
  if (audienciaC === "comité técnico") {
    if (maquilladaC) {
      const filas = t.estrategias.map((e, i) =&gt; [e, ...t.costos[i].slice(0, 4).map(f1), f1(t.cuatro.peorCaso[i]), f1(t.cuatro.arrepentimientoMaximo[i])]);
      return {texto: "El impulso FNCER (300 MW/año) es el más barato en los cuatro mundos de la matriz: maximin y minimax regret lo eligen con arrepentimiento cero.",
        tabla: {cabecera: ["COP/kWh", ...t.mundos.slice(0, 4), "Peor caso", "Máx. arrep."], filas}, grafica: null,
        elementos: [true, true, false, false], exceso: "ninguna"};
    }
    const texto = `Seis estrategias en cinco mundos, con la sequía de diseño y la energía no servida a ${f0(COSTO_RACIONAMIENTO)} COP/kWh del modelo. `
      + `El impulso FNCER es el más barato en los cinco (de ${f1(t.impMin)} a ${f1(t.impMax)} COP/kWh): maximin y minimax regret lo eligen. `
      + `En la sequía raciona hasta el ${p1(t.deficitSequia[t.imp])} de la demanda; el mercado solo, el ${p1(t.deficitSequia[t.mer])}. `
      + `Si se exige no racionar más del 0,1 %, maximin elige el ${t.estrategias[t.maximinAdm]} y minimax regret el «${t.estrategias[t.minimaxAdm]}», un cargo de unos 7 USD/MWh, que cuestan de ${f1(t.seguridadMin)} a ${f1(t.seguridadMax)} COP/kWh más. `
      + "El modelo no tiene intervención de precios en las crisis ni aversión al riesgo de los financiadores, que sostienen el cargo real.";
    const filas = t.estrategias.map((e, i) =&gt; [e, ...t.costos[i].map(f1), f1(t.peorCaso[i]), f1(t.arrepentimientoMaximo[i]), deficitTexto(t.deficitSequia[i])]);
    return {texto, tabla: {cabecera: ["COP/kWh", ...t.mundos, "Peor caso", "Máx. arrep.", "Raciona en la sequía"], filas}, grafica: null,
      elementos: [true, true, true, true], exceso: "ninguna"};
  }
  if (audienciaC === "comité directivo") {
    const texto = maquilladaC
      ? `Recomendamos contratar por subasta 300 MW renovables al año: es lo más barato en los cinco futuros, y dejar solo al mercado cuesta hasta un ${p0(t.mercadoRelMax)} más. Hoy les pedimos aprobar el programa.`
      : `Recomendamos contratar por subasta 300 MW renovables al año: es lo más barato en los cinco futuros, incluida una sequía como la que define la energía firme. `
        + `Sola, en esa sequía raciona hasta el ${p0(t.deficitSequia[t.imp])} de la demanda. Si el país no acepta ese riesgo, acompáñenla de una subasta de energía firme o de un cargo bajo, de unos 7 USD/MWh: `
        + `cualquiera de los dos cuesta entre el ${p0(t.seguridadRelMin)} y el ${p0(t.seguridadRelMax)} más. Revisen la decisión si El Niño se vuelve más frecuente o más severo; el modelo deja por fuera razones que sostienen el cargo real. `
        + "Hoy les pedimos aprobar el programa y fijar el criterio de confiabilidad.";
    return {texto, tabla: null, grafica: barras(!maquilladaC), elementos: [true, true, !maquilladaC, !maquilladaC], exceso: "ninguna"};
  }
  if (maquilladaC) {
    return {texto: "Proponemos traer nuevos parques de sol y viento a la región: la luz saldrá más barata y más segura para todos.",
      tabla: null, grafica: null, elementos: [false, true, false, false], exceso: "«más segura para todos»"};
  }
  const texto = "Recomendamos comprar cada año, en subastas, la energía de unos 300 megavatios nuevos de sol y viento en todo el país: es lo más barato en los cinco futuros que estudiamos. "
    + `Pero si llega una sequía muy fuerte, de dos años, y solo se hace eso, habría cortes de luz programados: en el peor momento faltarían casi ${Math.round(100 * t.deficitSequia[t.imp])} de cada 100 kilovatios hora. `
    + `Se pueden evitar con un seguro que pagan en la tarifa todos los usuarios conectados a la red, llegue la sequía o no: de cada 100 pesos que se pagan por la energía, sumaría entre ${Math.round(100 * t.seguridadRelMin)} y ${Math.round(100 * t.seguridadRelMax)}. `
    + "Decidir si se compra ese seguro le toca al Gobierno. El estudio usa un modelo simplificado y no sabe cuándo llegará una sequía así; si El Niño se vuelve más frecuente, la recomendación se revisa. "
    + "Esta decisión no define dónde se construye cada parque: eso pasa por la consulta previa con cada comunidad.";
  return {texto, tabla: null, grafica: null, elementos: [true, true, true, true], exceso: "ninguna"};
}









