  width: Math.min(width, 760), height: 340, marginLeft: 10, marginRight: 130, marginTop: 30,
  x: {label: "Costo adicional frente a la opción más barata, del mejor al peor futuro →", grid: true, tickFormat: (d) =&gt; formatoPorcentaje(d, 0),
    domain: [0, 1.05 * Math.max(...versionC.grafica.map((d) =&gt; d.max))]},
