    Plot.dot(versionC.grafica, {y: "nombre", x: "min", r: 4, fill: (d) =&gt; (maquilladaC ? COLORES.azul : d.raciona ? COLORES.rojo : COLORES.verde)}),
    Plot.text(versionC.grafica, {y: "nombre", x: 0, text: "nombre", dy: -14, textAnchor: "start", fill: COLORES.gris}),
    Plot.text(versionC.grafica, {y: "nombre", x: "max", text: "etiqueta", dx: 10, textAnchor: "start",
      fill: (d) =&gt; (d.raciona ? COLORES.rojo : COLORES.verde)}),
  ],
}) : html``









