viewof aportesV = Inputs.range([0.40, 1.00], {value: 1.00, step: 0.01, label: "Caja: aportes de la sequía por debajo de [fracción de la media]"})









Ver el código en Python
viewof anioV = Inputs.range([10, 35], {value: 10, step: 1, label: "Caja: la sequía empieza después del año"})









Ver el código en Python
vulnerabilidadV = {
  const f = futurosV.futuros;
  const impulso = futurosV.estrategias.indexOf("impulso FNCER"), cargo15 = futurosV.estrategias.indexOf("cargo 15 + FNCER 300");
  const puntos = futurosV.costos.map((c, i) =&gt; {
    const minimo = Math.min(...c);
    const arrepentimiento = c[impulso] - minimo;
    return {aportes: f.aportes_sequia[i], anio: f.anio_sequia[i], valor: f.costo_racionamiento[i], arrepentimiento,
      falla: arrepentimiento &gt; umbralV, ganaCargo15: c[cargo15] - minimo &lt; 1e-9,
      enCaja: f.aportes_sequia[i] &lt; aportesV && f.anio_sequia[i] &gt; anioV};
  });
  const media = (lista) =&gt; lista.reduce((a, b) =&gt; a + b, 0) / Math.max(lista.length, 1);
  const fallas = puntos.filter((p) =&gt; p.falla);
  const enCaja = puntos.filter((p) =&gt; p.enCaja).length;
  const fallasEnCaja = fallas.filter((p) =&gt; p.enCaja).length;
  return {puntos, fallas: fallas.length, enCaja, fallasEnCaja, total: puntos.length,
    cargo15EnFallas: fallas.filter((p) =&gt; p.ganaCargo15).length,
    valorFallas: media(fallas.map((p) =&gt; p.valor)), valorResto: media(puntos.filter((p) =&gt; !p.falla).map((p) =&gt; p.valor)),
    peor: Math.max(...puntos.map((p) =&gt; p.arrepentimiento)),
    cobertura: fallas.length ? fallasEnCaja / fallas.length : 0, densidad: enCaja ? fallasEnCaja / enCaja : 0};
}









