barridoB = {
  const def = {"retardo constructor": ["retardo_constructor_firme", Array.from({length: 13}, (_, k) =&gt; 2 + 0.5 * k), formatoNumero(1), "Retardo constructor [años]"],
    "crecimiento de la demanda": ["crecimiento_demanda", Array.from({length: 8}, (_, k) =&gt; 0.015 + 0.005 * k), (x) =&gt; formatoPorcentaje(x, 1), "Crecimiento de la demanda [1/año]"],
    "vida útil": ["vida_util_firme", Array.from({length: 7}, (_, k) =&gt; 20 + 5 * k), formatoNumero(0), "Vida útil firme [años]"]}[parametroB];
  const [clave, valores, formato, etiqueta] = def;
  const desde = ventanaB === "desde el año 5" ? 5 : 15;
  const medir = (x, reescalar, d) =&gt; amplitudDesde(correrS({[clave]: x,
    ...(reescalar ? {proyectos_firme_iniciales: carteraReescalada({[clave]: x})} : {})}), d);
  const gris = valores.map((x) =&gt; ({x, a: medir(x, false, 5)}));
  const azul = valores.map((x) =&gt; ({x, a: medir(x, reescalaB, desde)}));
  const minimo = azul.reduce((m, f) =&gt; (f.a &lt; m.a ? f : m));
  const base = azul.find((f) =&gt; Math.abs(f.x - CASO[clave]) &lt; 1e-9);
  return {gris, azul, minimo, base, formato, etiqueta, primero: azul[0], ultimo: azul.at(-1), caso: CASO[clave]};
}









