NotaEl tornado en Python






from mise_sd.core import integrar
from mise_sd.modelos import mercado_con_politicas

caso = {"retardo_constructor_firme": 4.0, "sensibilidad_precio": 3.0, "elasticidad_inversion": 3.0,
        "crecimiento_demanda": 0.03, "vida_util_firme": 30.0, "tiempo_expectativas": 1.0, "tasa_aprendizaje": 0.10}

def cartera_reescalada(p):
    """Cartera inicial con la misma razón a la cartera normal τc (1/L + g) que el caso base."""
    return 3000.0 * p["retardo_constructor_firme"] * (1 / p["vida_util_firme"] + p["crecimiento_demanda"]) / (4.0 * (1 / 30 + 0.03))

def amplitud_desde_el_5(reescalar=False, **cambios):
    p = {**caso, **cambios}
    if reescalar:
        p["proyectos_firme_iniciales"] = cartera_reescalada(p)
    r = integrar(mercado_con_politicas(**p), t_final=40.0, paso_salida=0.05)
    margen = r["margen_energia"][r.tiempo &gt;= 5]
    return margen.max() - margen.min()

base = amplitud_desde_el_5()
for reescalar in (False, True):
    print("cartera reescalada" if reescalar else "cartera fija", f"(caso base {base:.4f})")
    for nombre, valor in caso.items():
        bajo = amplitud_desde_el_5(reescalar, **{nombre: 0.75 * valor})
        alto = amplitud_desde_el_5(reescalar, **{nombre: 1.25 * valor})
        print(f"   {nombre:26s} {bajo:.4f} a {alto:.4f}")

