rangos = {"caida_costo_global": (0.05, 0.25), "crecimiento_demanda": (0.015, 0.05),
          "intensidad_nino": (0.20, 0.45), "periodo_nino": (3.0, 8.0),
          "aportes_sequia": (0.40, 1.00), "anio_sequia": (10.0, 35.0),
          "costo_racionamiento": (1500.0, 10000.0)}
generador = np.random.default_rng(2026)
futuros = {f: generador.uniform(a, b, 100) for f, (a, b) in rangos.items()}
estrategias = list(lab4.ESTRATEGIAS)
costos = np.empty((100, len(estrategias)))
for i in range(100):
    f = {k: float(v[i]) for k, v in futuros.items()}

    def hidrologia(t, f=f):
        # El Niño recurrente (1,5 años desde el año 8) por la sequía de 2 años en su año
        return ((1 - f["intensidad_nino"] * pulso_nino(t, f["periodo_nino"], 1.5, 8.0, 0.25))
                * (1 - (1 - f["aportes_sequia"]) * pulso_nino(t, 100.0, 2.0, f["anio_sequia"], 0.25)))

    quiebres = sorted(quiebres_nino(f["periodo_nino"], 1.5, 8.0, 0.25, 40.0)
                      + quiebres_nino(100.0, 2.0, f["anio_sequia"], 0.25, 40.0))
    for j, estrategia in enumerate(estrategias):
        parametros = {"caida_costo_global": f["caida_costo_global"], "crecimiento_demanda": f["crecimiento_demanda"],
                      "factor_hidrologico": hidrologia, **lab4.ESTRATEGIAS[estrategia]}
        r = integrar(mercado_con_politicas(**parametros), t_final=40.0, paso_salida=0.05, puntos_quiebre=quiebres)
        serie = r["precio_demanda"] + f["costo_racionamiento"] * r["deficit"] / r["demanda"]
        costos[i, j] = lab4.media_temporal(r.tiempo, serie)
arrepentimiento = costos - costos.min(axis=1, keepdims=True)
X = np.column_stack(list(futuros.values()))

def coeficientes_estandarizados(y, con_rangos=False):
    """Regresión de y sobre los factores, todo estandarizado; devuelve (SRC, R²)."""
    x = X
    if con_rangos:
        x, y = np.column_stack([rankdata(c) for c in X.T]), rankdata(y)
    z_x, z = (x - x.mean(axis=0)) / x.std(axis=0), (y - y.mean()) / y.std()
    diseno = np.column_stack([np.ones(len(z)), z_x])
    b, *_ = np.linalg.lstsq(diseno, z, rcond=None)
    return b[1:], 1 - np.sum((z - diseno @ b) ** 2) / np.sum((z - z.mean()) ** 2)

impulso = estrategias.index("impulso FNCER")
salidas = {"costo del mercado solo": costos[:, estrategias.index("mercado solo")],
           "arrepentimiento del impulso FNCER": arrepentimiento[:, impulso]}
resultados = {}
for nombre, y in salidas.items():
    src, r2 = coeficientes_estandarizados(y)
    srrc, r2_rangos = coeficientes_estandarizados(y, con_rangos=True)
    resultados[nombre] = (src, r2)
    print(f"{nombre}: media {y.mean():.2f}, de {y.min():.2f} a {y.max():.2f} COP/kWh; "
          f"R² lineal {r2:.2f}, con rangos {r2_rangos:.2f}")
    for factor, a, b in zip(rangos, src, srrc):
        print(f"   {factor:20s} SRC {a:+.2f}   con rangos {b:+.2f}")
cola = arrepentimiento[:, impulso] &gt; 1
