Ver el código en Python
refuerzoR = {
  const paso = 0.05;
  const en = (anio) =&gt; Math.round(anio / paso);
  const correr = (lr, cb) =&gt; simular(mercadoConPoliticas({tasa_aprendizaje: lr, canibalizacion: cb}), {tFinal: 40, paso});
  const r = correr(aprendizajeR, canibalizacionR);
  const base = correr(0.1, 2.5);
  const v = r.variables, b = base.variables;
  const tasa = (s, k) =&gt; (s.puesta_fncer[k] - s.retiros_fncer[k]) / s.capacidad_fncer[k];
  const g4 = tasa(v, en(4)), k4 = v.capacidad_fncer[en(4)];
  const extrapolada = r.tiempo.filter((t) =&gt; t &gt;= 4 && t &lt;= 20).map((t) =&gt; ({t, K: k4 * Math.exp(g4 * (t - 4)) / 1000}));
  const filas = r.tiempo.map((t, k) =&gt; ({t, K: v.capacidad_fncer[k] / 1000, g: tasa(v, k)}));
  const filasBase = base.tiempo.map((t, k) =&gt; ({t, K: b.capacidad_fncer[k] / 1000, g: tasa(b, k)}));
  const capacidades = [...filas, ...filasBase, ...extrapolada].map((d) =&gt; d.K);
  const tasas = [...filas, ...filasBase].filter((d) =&gt; d.t &gt;= 0.5).map((d) =&gt; d.g);
  return {
    filas, base: filasBase, extrapolada,
    dominioK: [0.8 * Math.min(...capacidades), 1.25 * Math.max(...capacidades)],
    dominioG: [0, 1.1 * Math.max(...tasas)],
    k10: v.capacidad_fncer[en(10)], k20: v.capacidad_fncer[en(20)], k40: v.capacidad_fncer[en(40)],
    g4, g40: tasa(v, en(40)), extrapolada20: extrapolada.at(-1).K * 1000,
    participacion40: v.participacion_aprovechada_fncer[en(40)], costo40: v.costo_fncer[en(40)],
  };
}









