Ver el código en Python
analisisC = {
  const g = grafo(stnC.aristas.map((e) =&gt; [e.a, e.b]), stnC.nodos.map((n) =&gt; n.id));
  const posicion = Object.fromEntries(stnC.nodos.map((n) =&gt; [n.id, n]));
  const camino = origenC === destinoC ? [origenC] : caminoMasCorto(g, origenC, destinoC);
  const adyacentes = g.vecinos.get(origenC).includes(destinoC);
  const corteA = origenC === destinoC ? [] : corteMinimoAristas(g, [origenC], [destinoC]);
  const corteV = origenC === destinoC || adyacentes ? [] : corteMinimoVertices(g, [origenC], [destinoC]);
  const enCorte = new Set(corteA.map(([a, b]) =&gt; `${a}|${b}`));
  const clave = (a, b) =&gt; (String(a) &lt; String(b) ? `${a}|${b}` : `${b}|${a}`);
  // Un corredor de 500 kV cuyo trazo recto pasaría sobre otra subestación de 500 kV
  // (Porce III-Sogamoso sobre Primavera) se dibuja en arco hacia el norte, como en las notas
  const de500 = stnC.nodos.filter((n) =&gt; n.tension_kv === 500);
  const trazo = (e) =&gt; {
    const a = posicion[e.a], b = posicion[e.b], dx = b.lon - a.lon, dy = b.lat - a.lat, l2 = dx * dx + dy * dy;
    const tapa = e.tension_kv === 500 && de500.some((w) =&gt; {
      if (w.id === e.a || w.id === e.b) return false;
      const t = ((w.lon - a.lon) * dx + (w.lat - a.lat) * dy) / l2;
      return t &gt; 0.05 && t &lt; 0.95 && Math.hypot(a.lon + t * dx - w.lon, a.lat + t * dy - w.lat) &lt; 0.12;
    });
    if (!tapa) return [{x: a.lon, y: a.lat}, {x: b.lon, y: b.lat}];
    const signo = dx &gt;= 0 ? 1 : -1;
    const cx = (a.lon + b.lon) / 2 - signo * 0.3 * dy, cy = (a.lat + b.lat) / 2 + signo * 0.3 * dx;
    return Array.from({length: 21}, (_, i) =&gt; {
      const s = i / 20;
      return {x: (1 - s) ** 2 * a.lon + 2 * s * (1 - s) * cx + s * s * b.lon, y: (1 - s) ** 2 * a.lat + 2 * s * (1 - s) * cy + s * s * b.lat};
    });
  };
  const trazos = new Map(stnC.aristas.map((e) =&gt; [clave(e.a, e.b), trazo(e)]));
  const lineas = stnC.aristas.flatMap((e) =&gt; {
    const k = clave(e.a, e.b);
    return trazos.get(k).map((p) =&gt; ({...p, clave: k, corte: enCorte.has(k)}));
  });
  const tramos = camino ? camino.slice(1).flatMap((n, i) =&gt; {
    const k = clave(camino[i], n);
    return trazos.get(k).map((p) =&gt; ({...p, clave: k}));
  }) : [];
  const km = camino ? camino.slice(1).reduce((suma, n, i) =&gt; {
    const e = stnC.aristas.find((x) =&gt; (x.a === camino[i] && x.b === n) || (x.b === camino[i] && x.a === n));
    return suma + (e ? e.longitud_km : 0);
  }, 0) : 0;
  return {lineas, tramos, camino, corteA, corteV, adyacentes, km,
    nodos: stnC.nodos.map((n) =&gt; ({...n, enCorte: corteV.includes(n.id), extremo: n.id === origenC || n.id === destinoC}))};
}









