medidasG = {
  const grado = {}, fuerza = {};
  for (const n of stnG.nodos) { grado[n.id] = 0; fuerza[n.id] = 0; }
  for (const e of stnG.aristas) {
    grado[e.a]++; grado[e.b]++;
    fuerza[e.a] += e.capacidad_mw; fuerza[e.b] += e.capacidad_mw;
  }
  const nodos = stnG.nodos.filter((n) =&gt; regionG === "todo el sistema" || n.region === regionG)
    .map((n) =&gt; ({...n, grado: grado[n.id], fuerza: fuerza[n.id]}));
  const usaGrado = medidaG.startsWith("grado");
  const valores = nodos.map((n) =&gt; (usaGrado ? n.grado : n.fuerza)).sort((a, b) =&gt; a - b);
  const distintos = [...new Set(valores)];
  const ccdf = distintos.map((k) =&gt; ({k, P: valores.filter((v) =&gt; v &gt;= k).length / valores.length}));
  const mayor = nodos.reduce((m, n) =&gt; ((usaGrado ? n.grado : n.fuerza) &gt; (usaGrado ? m.grado : m.fuerza) ? n : m), nodos[0]);
  return {nodos, usaGrado, valores, ccdf, mayor,
    media: valores.reduce((a, b) =&gt; a + b, 0) / valores.length,
    ramales: nodos.filter((n) =&gt; n.grado === 1).length,
    tresOmas: nodos.filter((n) =&gt; n.grado &gt;= 3).length / nodos.length,
    densidad: 2 * stnG.aristas.length / (stnG.nodos.length * (stnG.nodos.length - 1))};
}









