  return {serie: [...serie(base, "sin eólica guajira"), ...(casoM === "sin eólica guajira" ? [] : serie(caso, casoM))],
    precio: media(caso, "precio_bolsa"), cambio: media(caso, "precio_bolsa") - media(base, "precio_bolsa"),
