tableroR = {
  const s = (i) =&gt; senalesR.includes(SENALES[i]);
  const recs = [
    {n: 1, titulo: "Gobernar la evacuación por corredor", reacciones: [
      s(0) && {tipo: "revisar", texto: "Priorizar el tramo Colectora–Cuestecitas y auditar los acuerdos que podrían reabrirlo."},
      s(1) && {tipo: "revisar", texto: "Adelantar el segundo punto de conexión y consultar su trazado desde el inicio a escala territorial."}]},
    {n: 2, titulo: "Crear y financiar el nivel territorial", reacciones: [
      s(2) && {tipo: "validez", texto: "Rediseñar la representación con las autoridades antes de seguir."},
      s(3) && {tipo: "revisar", texto: "Auditar la instancia y revisar la regla de reparto en partes iguales, que premia el número de comunidades acreditadas y no la afectación."}]},
    {n: 3, titulo: "Regular el ritmo, además del volumen", reacciones: [
      s(4) && {tipo: "revisar", texto: "Frenar nuevas adjudicaciones en el territorio y coordinar las consultas en curso: más subasta termina en proyectos abandonados."}]},
    {n: 4, titulo: "Medir la licencia social como el margen", reacciones: [
      s(5) && {tipo: "revisar", texto: "Alerta temprana de bloqueos: activar las instancias de resolución de conflictos antes de que escalen."}]},
  ].map((r) =&gt; ({...r, reacciones: r.reacciones.filter(Boolean)}));
  return recs.map((r) =&gt; ({...r, estado: r.reacciones.some((x) =&gt; x.tipo === "validez") ? "validez" : r.reacciones.length ? "revisar" : "vigente"}));
}









